package d2svgimport
import("context";"encoding/json";"os";"strings";"testing")
func TestCodexMathScene(t *testing.T){data,e:=os.ReadFile(os.Getenv("CODEX_SCENE_INPUT"));if e!=nil{t.Fatal(e)};var requests []struct{Expression string `json:"expression"`;SVG string `json:"svg"`};if e=json.Unmarshal(data,&requests);e!=nil{t.Fatal(e)};rows:=[]map[string]any{};limits:=Limits{MaxBytes:10000000,MaxDepth:1000,MaxElements:100000,MaxAttributes:100000,MaxAttributeBytes:10000000,MaxPathCommands:1000000,MaxTransformFunctions:100000,MaxUseDepth:100,MaxResources:100000};for _,r:=range requests {result,e:=ImportNode(context.Background(),"probe",[]byte(r.SVG),limits);row:=map[string]any{"expression":r.Expression,"svg":r.SVG,"error":""};if e!=nil{row["error"]=strings.TrimPrefix(e.Error(),"d2svgimport: probe: ")}else{row["scene"]=result};rows=append(rows,row)};out,e:=json.MarshalIndent(rows,"","  ");if e!=nil{t.Fatal(e)};if e=os.WriteFile(os.Getenv("CODEX_SCENE_OUTPUT"),append(out,'\n'),0644);e!=nil{t.Fatal(e)}}
